create table public.ai_rate_limits(user_id uuid primary key references auth.users(id) on delete cascade,window_started_at timestamptz not null default now(),request_count integer not null default 0 check(request_count>=0));
create or replace function public.consume_ai_rate_limit(p_limit integer default 5,p_window_seconds integer default 60) returns boolean language plpgsql security definer set search_path=public as $$ declare v_count integer; begin if auth.uid() is null then return false;end if;if p_limit<1 or p_window_seconds<1 then raise exception 'invalid rate limit';end if;insert into public.ai_rate_limits(user_id,window_started_at,request_count) values(auth.uid(),now(),1) on conflict(user_id) do update set window_started_at=case when public.ai_rate_limits.window_started_at <= now()-make_interval(secs=>p_window_seconds) then now() else public.ai_rate_limits.window_started_at end,request_count=case when public.ai_rate_limits.window_started_at <= now()-make_interval(secs=>p_window_seconds) then 1 else public.ai_rate_limits.request_count+1 end returning request_count into v_count;return v_count<=p_limit;end; $$;
grant execute on function public.consume_ai_rate_limit(integer,integer) to authenticated;
alter table public.ai_rate_limits enable row level security;